update public.cultivars set origins = $j$[{"body":"Anthurium warocqueanum は 1878 年、T.Moore が Florist & Pomol. 101, figs で記載した。タイプ産地は Colombia。分布は Colombia（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-04-02","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium warocqueanum was described by T.Moore in 1878 in Florist & Pomol. 101, figs. Type locality: Colombia. Distribution: Colombia (POWO).","sources":[{"url":"https://www.ipni.org/n/85496-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85496-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85496-1","structured":{"notes":"","collector":null,"author_name":"T.Moore","origin_type":"species","type_locality":"Colombia","citation_links":[{"url":"https://www.ipni.org/n/85496-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85496-1","label":"POWO (Kew)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":1878},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":1878,"source_language":"en","first_description":"T.Moore, Florist & Pomol. 101, figs (1878)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"T.Moore"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 4;
update public.cultivars set origins = $j$[{"body":"Anthurium 'Dark Mama'は、Anthurium warocqueanumとAnthurium papillilaminumの交配から生まれたクローン品種です。作出者や発見年は不明ですが、プライベートブリーダーによって開発されたと考えられています。この品種は、独自の暗色の葉や茎を持つことが特徴です。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-04-02","isAI":true,"name":"AI (Llama 3.3 70B)"},"body_en":"Anthurium 'Dark Mama' is a clone cultivar that originated from the cross of Anthurium warocqueanum and Anthurium papillilaminum. The exact breeder and discovery year are unknown, but it is believed to have been developed by a private breeder. This cultivar is distinct from the typical species form due to its unique dark-colored leaves and stems.","sources":[],"verified":false,"parentage":"Anthurium warocqueanum × Anthurium papillilaminum","source_url":null,"structured":{"namer":null,"notes":"Anthurium 'Dark Mama'は、Anthurium warocqueanumとAnthurium papillilaminumの交配から生まれたクローン品種です。作出者や発見年は不明ですが、プライベートブリーダーによって開発されたと考えられています。この品種は、独自の暗色の葉や茎を持つことが特徴です。","formula":{"parentA":"Anthurium warocqueanum","parentB":"Anthurium papillilaminum"},"naming_year":null,"origin_type":"clone","citation_links":[],"collector":null},"trustClass":"trust--low","source_name":"Aroid collector community","source_tier":"D","source_type":"ai_research","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":null}]$j$::jsonb, name_status = $q$disputed$q$, aliases = array[$q$Dark Momma$q$]::text[], formula_status = $q$known$q$, parent_b_id = 32, parent_b_text = $q$Anthurium papillilaminum$q$, updated_at = now() where id = 5;
update public.cultivars set origins = $j$[{"body":"Anthurium veitchii は 1876 年、Mast. が Gard. Chron. n.s., 775 で記載した。タイプ産地は Chocó, Colombia。分布は Colombia（POWO）。","trust":95,"votes":{"agree":1,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium veitchii was described by Mast. in 1876 in Gard. Chron. n.s., 775. Type locality: Chocó, Colombia. Distribution: Colombia (POWO).","sources":[{"url":"https://www.ipni.org/n/85473-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85473-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85473-1","structured":{"notes":"","collector":null,"author_name":"Mast.","origin_type":"species","type_locality":"Chocó, Colombia","citation_links":[{"url":"https://www.ipni.org/n/85473-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85473-1","label":"POWO (Kew)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":1876},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":1876,"source_language":"en","first_description":"Mast., Gard. Chron. n.s., 775 (1876)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Mast."}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 6;
update public.cultivars set origins = $j$[{"body":"Anthurium 'Ace of Spades' は、フロリダのナーセリーである The Orchid Jungle にて管理されていた、南米採集の未同定株に由来する選抜個体である。\n\nこの母株は当初 Anthurium hoffmannii としてラベルされていたが、形態的特徴からその同定には疑問があり、正確な種同定はされていない。\n\n採集地では単独で存在していたとされ、自家受粉、もしくは自然交雑により得られた種子から実生が育成された。その後、Denis Rotolante によって播種され、得られた実生群の中から特に優れた形質を持つ個体が選抜され 'Ace of Spades' と命名された。\n\nそのため本個体は明確な交配式を持つ人工交配種ではなく、自然由来の遺伝背景を持つ実生選抜クローンと考えられている。","trust":23,"votes":{"agree":1,"disagree":0},"author":{"isAI":false,"name":"User"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"namer":"Denis Rotolante (SKG)","notes":"Anthurium ‘Ace of Spades’ は、フロリダのナーセリーである The Orchid Jungle にて管理されていた、南米採集の未同定株に由来する選抜個体である。\n\nこの母株は当初 Anthurium hoffmannii としてラベルされていたが、形態的特徴からその同定には疑問があり、正確な種同定はされていない。\n\n採集地では単独で存在していたとされ、自家受粉、もしくは自然交雑により得られた種子から実生が育成された。その後、Denis Rotolante によって播種され、得られた実生群の中から特に優れた形質を持つ個体が選抜され ‘Ace of Spades’ と命名された。\n\nそのため本個体は明確な交配式を持つ人工交配種ではなく、自然由来の遺伝背景を持つ実生選抜クローンと考えられている。","naming_year":null,"origin_type":"clone","citation_links":[],"collector":null},"trustClass":"trust--low","source_name":null,"source_tier":"D","source_type":"manual","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":null}]$j$::jsonb, name_status = null, aliases = null, formula_status = $q$unknown$q$, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 7;
