update public.cultivars set origins = $j$[{"body":"Anthurium clarinervium は 1952 年、Matuda が Anales Inst. Biol. Univ. Nac. México 22: 375, fig. 4 で記載した。タイプ産地は Mexico, Chiapas。採集者は E. Matuda（1949 年採集）。分布は Mexico（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium clarinervium was described by Matuda in 1952 in Anales Inst. Biol. Univ. Nac. México 22: 375, fig. 4. Type locality: Mexico, Chiapas. Collected by E. Matuda (1949). Distribution: Mexico (POWO).","sources":[{"url":"https://www.ipni.org/n/15185-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15185-2","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15185-2","structured":{"notes":"","collector":"E. Matuda","author_name":"Matuda","origin_type":"species","type_locality":"Mexico, Chiapas","citation_links":[{"url":"https://www.ipni.org/n/15185-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15185-2","label":"POWO (Kew)"}],"known_habitats":"Mexico","collection_year":1949,"publication_year":1952},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Mexico","discovery_year":1952,"source_language":"en","first_description":"Matuda, Anales Inst. Biol. Univ. Nac. México 22: 375, fig. 4 (1952)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Matuda"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 9;
