update public.cultivars set origins = $j$[{"body":"Anthurium forgetii は 1906 年、N.E.Br. が Gard. Chron. ser. 3, 39: 161 で記載した。タイプ産地は Colombia。分布は Colombia（POWO）。種小名は採集者 Forget への献名（IPNI）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-08-23","isAI":true,"name":"GBIF / Kew"},"body_en":"Anthurium forgetii was described by N.E.Br. in 1906 in Gard. Chron. ser. 3, 39: 161. Type locality: Colombia. Distribution: Colombia (POWO). The epithet honours the collector Forget (IPNI).","sources":[{"url":"https://www.gbif.org/species/2873656","label":"GBIF (Kew Backbone)"},{"url":"https://powo.science.kew.org/results?q=Anthurium%20forgetii","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://www.gbif.org/species/2873656","structured":{"notes":"","collector":null,"author_name":"N.E.Br.","origin_type":"species","type_locality":"Colombia","citation_links":[{"url":"https://www.ipni.org/n/15285-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15285-2","label":"POWO (Kew)"},{"url":"https://www.gbif.org/species/2873656","label":"GBIF (Kew Backbone)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":1906},"trustClass":"trust--high","source_name":"GBIF / Kew Backbone Taxonomy","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":1906,"source_language":"en","first_description":"N.E.Br., Gard. Chron. ser. 3, 39: 161 (1906)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"N.E.Br."},{"body":"発表者: N.E.Br. (1906). 採取地: Colombia. 生息地: 熱帯雨林、標高の低い地域の着生植物. Anthurium forgetiiは、葉が心形で濃緑色をしている。葉の表面は光沢があり、葉脈は明瞭に表現されている。植物全体にワックスのような質感がある。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-04-02","isAI":false,"name":"User"},"body_en":"Anthurium forgetii has heart-shaped leaves with a glossy surface and prominent venation.The overall plant has a waxy texture.","sources":[{"url":"https://www.ipni.org/n/15285-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15285-2","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15285-2","structured":{"notes":"Anthurium forgetiiは、葉が心形で濃緑色をしている。葉の表面は光沢があり、葉脈は明瞭に表現されている。葉柄は太く、長さが約30cmである。植物全体にワックスのような質感がある。","collector":null,"author_name":"N.E.Br.","origin_type":"species","type_locality":"Colombia","known_habitats":"熱帯雨林、標高の低い地域の着生植物","publication_year":1906,"species_subcategory":"species"},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"manual","native_region":"Colombia","discovery_year":1906,"source_language":"en","first_description":"N.E.Br., Gard. Chron. ser. 3, 39: 161 (1906)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"N.E.Br."}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 11;
