update public.cultivars set origins = $j$[{"body":"Philodendron gloriosum × P. melanochrysum の交配種。Keith Henderson により 1975 年に作出されたとされ、IAS の栽培品種登録では Hybrid として記録されている。種子・組織培養の両方で流通する。","trust":23,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-14","isAI":true,"name":"AI (Llama 3.3 70B)"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"notes":"Philodendron gloriosum × P. melanochrysum の交配種。Keith Henderson により 1975 年に作出されたとされ、IAS の栽培品種登録では Hybrid として記録されている。種子・組織培養の両方で流通する。","breeder":"Keith Henderson","formula":{"parentA":"Philodendron gloriosum","parentB":"Philodendron melanochrysum"},"naming_year":1975,"origin_type":"hybrid","collector":null},"trustClass":"trust--low","source_name":"Training data","source_tier":"D","source_type":"ai_research","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":null}]$j$::jsonb, name_status = null, aliases = null, formula_status = $q$known$q$, parent_b_id = 23, parent_b_text = $q$Philodendron melanochrysum$q$, updated_at = now() where id = 24;
update public.cultivars set origins = $j$[{"body":"Philodendron rubrijuvenileはT. B. CroatとR. KaufmannがAroideana（45(1):214, 31 Jan 2022）で正式に記載した種で、標本はT. Croat & R. Kaufmann 107898（採集日 2020-09-09）を基にしています。タイプ材料はRon Kaufmann（San Diego, CA）で栽培されたもので、採地情報は報告上Colombiaと記載されています。園芸的には長く'El Chocó Red'の名称で流通していました。若葉は葉裏が鮮赤色で、葉面は濃緑のベルベット状、蔓性のクライマーとして知られます。","trust":89,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-09-04","isAI":true,"name":"AI (gpt-5-mini + Web検索)"},"body_en":"Philodendron rubrijuvenile was formally described by T. B. Croat & R. Kaufmann in Aroideana (45(1):214) published 31 January 2022. The protologue is based on material collected as T. Croat & R. Kaufmann 107898 (collection date 9 Sep 2020) and the holotype is deposited at MO (MO-6939298 et seq.); isotypes are cited at COL, K and US. The type material was grown in cultivation by Ron Kaufmann in San Diego, CA, and the published type information records provenance as Colombia; Kew's Plants of the World Online lists the native range as Colombia. The name had long circulated in horticulture under the trade name 'El Chocó Red' prior to formal description. Vegetatively the plant is a vining/hemiepiphytic Philodendron with juvenile leaves showing a crimson-red abaxial surface (hence the epithet), velvety texture, and dark green adaxial surface; Croat's discussion of the species notes the lack of scales on internodes and related structures in herbarium material. Sources: Croat & R. Kaufmann (Aroideana 2022), IPNI, POWO.","sources":[{"url":"https://www.ipni.org/n/77301584-1","label":"Aroideana (Croat & R. Kaufmann, 2022) / IPNI / Kew POWO"}],"verified":false,"parentage":null,"source_url":"https://www.ipni.org/n/77301584-1","structured":{"notes":"","collector":null,"author_name":"T. B. Croat & R. Kaufmann (Ron Kaufmann involved in cultivated material)","origin_type":"species","type_locality":"Colombia","citation_links":[{"url":"https://www.ipni.org/n/77301584-1","label":"Aroideana (Croat & R. Kaufmann, 2022) / IPNI / Kew POWO"}],"known_habitats":"Colombia","collection_year":null,"publication_year":2020},"trustClass":"trust--high","source_name":"Aroideana (Croat & R. Kaufmann, 2022) / IPNI / Kew POWO","source_tier":"A","source_type":"ai_research","native_region":"Colombia","discovery_year":2020,"source_language":"en","first_description":"T. B. Croat & R. Kaufmann, Aroideana 45(1): 214 (31 Jan 2022)","source_tier_label_en":"Academic Paper / Taxonomic Journal","source_tier_label_jp":"学術論文・分類学ジャーナル","discoverer_or_breeder":"T. B. Croat & R. Kaufmann (Ron Kaufmann involved in cultivated material)"}]$j$::jsonb, name_status = $q$trade$q$, aliases = array[$q$El Choco Red$q$]::text[], formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 26;
update public.cultivars set origins = $j$[{"body":"Philodendron verrucosum × P. melanochrysum の交配種として広く知られる。両親の特徴を受け継ぎ、ビロード質の暗緑色の葉に明るい葉脈が走り、葉柄には P. verrucosum に似た毛状突起が見られることがある。","trust":20,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-13","isAI":true,"name":"System"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"notes":"Philodendron verrucosum × P. melanochrysum の交配種として広く知られる。両親の特徴を受け継ぎ、ビロード質の暗緑色の葉に明るい葉脈が走り、葉柄には P. verrucosum に似た毛状突起が見られることがある。","formula":{"parentA":"Philodendron verrucosum","parentB":"Philodendron melanochrysum"},"origin_type":"hybrid","collector":null},"trustClass":"trust--low","source_name":"No source available","source_tier":"D","source_type":"none","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":null}]$j$::jsonb, name_status = null, aliases = null, formula_status = $q$known$q$, parent_b_id = 23, parent_b_text = $q$Philodendron melanochrysum$q$, updated_at = now() where id = 27;
