update public.cultivars set origins = $j$[{"body":"Anthurium debile は 2004 年、Croat & D.C.Bay が Aroideana 27: 97 (-99; figs. 9-11) で記載した。タイプ産地は Bajo Calima Region, Buenaventura-Malaga, Valle del Cauca, Colombia。分布は Colombia（POWO）。原記載では debilis と綴られた。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium debile was described by Croat & D.C.Bay in 2004 in Aroideana 27: 97 (-99; figs. 9-11). Type locality: Bajo Calima Region, Buenaventura-Malaga, Valle del Cauca, Colombia. Distribution: Colombia (POWO). Spelled 'debilis' in the protologue.","sources":[{"url":"https://www.ipni.org/n/60436403-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60436403-2","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60436403-2","structured":{"notes":"採集者は原記載で未確認のため空欄。","collector":null,"author_name":"Croat & D.C.Bay","origin_type":"species","type_locality":"Bajo Calima Region, Buenaventura-Malaga, Valle del Cauca, Colombia","citation_links":[{"url":"https://www.ipni.org/n/60436403-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60436403-2","label":"POWO (Kew)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":2004},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":2004,"source_language":"en","first_description":"Croat & D.C.Bay, Aroideana 27: 97 (-99; figs. 9-11) (2004)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Croat & D.C.Bay"}]$j$::jsonb, name_status = null, aliases = array[$q$debilis$q$]::text[], formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 34;
update public.cultivars set origins = $j$[{"body":"Anthurium splendidum は 1884 年、W.Bull ex Rodigas が Ill. Hort. 31: 13, t. 510 で記載した。タイプ産地は Colombia。分布は Colombia（POWO）。1883 年に Gard. Chron. n.s. 19: 381 で W.Bull の名により先行して英文発表されている。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium splendidum was described by W.Bull ex Rodigas in 1884 in Ill. Hort. 31: 13, t. 510. Type locality: Colombia. Distribution: Colombia (POWO). First announced in English as W.Bull in Gard. Chron. n.s. 19: 381 (1883).","sources":[{"url":"https://www.ipni.org/n/85368-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85368-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85368-1","structured":{"notes":"","collector":null,"author_name":"W.Bull ex Rodigas","origin_type":"species","type_locality":"Colombia","citation_links":[{"url":"https://www.ipni.org/n/85368-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85368-1","label":"POWO (Kew)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":1884},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":1884,"source_language":"en","first_description":"W.Bull ex Rodigas, Ill. Hort. 31: 13, t. 510 (1884)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"W.Bull"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 35;
update public.cultivars set origins = $j$[{"body":"Anthurium kunayalense は 2010 年、Croat & Vannini が Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C) で記載した。タイプ産地は Panama Province, along the road from El Llano to Carti, near km 12.5, near radio tower。採集者は J. Vannini（2007 年採集）。分布は Panama（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium kunayalense was described by Croat & Vannini in 2010 in Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C). Type locality: Panama Province, along the road from El Llano to Carti, near km 12.5, near radio tower. Collected by J. Vannini (2007). Distribution: Panama (POWO).","sources":[{"url":"https://www.ipni.org/n/77107445-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","structured":{"notes":"","collector":"J. Vannini","author_name":"Croat & Vannini","origin_type":"species","type_locality":"Panama Province, along the road from El Llano to Carti, near km 12.5, near radio tower","citation_links":[{"url":"https://www.ipni.org/n/77107445-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","label":"POWO (Kew)"}],"known_habitats":"Panama","collection_year":2007,"publication_year":2010},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Panama","discovery_year":2010,"source_language":"en","first_description":"Croat & Vannini, Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C) (2010)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Croat & Vannini"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 3