update public.cultivars set origins = $j$[{"body":"Anthurium 'Red Crystallinum' は、一般的な Anthurium crystallinum とは異なる園芸系統で、Tim Anderson が保有していた個体群に由来するとされる。\n\nこれらの個体は交配由来と考えられているが、親種は不明であり、'Wonderboy' と呼ばれる系統の関与が指摘されているものの、確証はない。\n\nその後、この系統に属する複数の個体が分けられ、NSE Tropicals、Tezula Plants、および Docblock にそれぞれ別個体として渡ったとされる。\n\n各所でこれらの個体の実生化が行われたため、現在 \"Red crystallinum\" の名称は単一のクローンではなく、共通した特徴を持つ複数の系統（クローンおよびその実生群）を含む総称として用いられている。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":false,"name":"User"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"notes":"Anthurium ‘Red crystallinum’ は、一般的な Anthurium crystallinum とは異なる園芸系統で、Tim Anderson が保有していた個体群に由来するとされる。\n\nこれらの個体は交配由来と考えられているが、親種は不明であり、“Wonderboy” と呼ばれる系統の関与が指摘されているものの、確証はない。\n\nその後、この系統に属する複数の個体が分けられ、NSE Tropicals、Tezula Plants、および Docblock にそれぞれ別個体として渡ったとされる。\n\n各所でこれらの個体の実生化が行われたため、現在 “Red crystallinum” の名称は単一のクローンではなく、共通した特徴を持つ複数の系統（クローンおよびその実生群）を含む総称として用いられている。","breeder":"Tim Anderson","naming_year":null,"origin_type":"hybrid","citation_links":[],"collector":null},"trustClass":"trust--low","source_name":null,"source_tier":null,"source_type":"manual","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":null,"source_tier_label_jp":null,"discoverer_or_breeder":null}]$j$::jsonb, name_status = $q$trade$q$, aliases = array[$q$Red crystallinum$q$]::text[], formula_status = $q$complex$q$, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 52;
