update public.cultivars set origins = $j$[{"body":"Anthurium luxurians は 2005 年、Croat & R.N.Cirino が Aroideana 28: 56 (-58; fig. 2) で記載した。タイプ産地は Colombia。分布は Colombia（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium luxurians was described by Croat & R.N.Cirino in 2005 in Aroideana 28: 56 (-58; fig. 2). Type locality: Colombia. Distribution: Colombia (POWO).","sources":[{"url":"https://www.ipni.org/n/60439860-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60439860-2","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60439860-2","structured":{"notes":"採集者は原記載で未確認のため空欄。","collector":null,"author_name":"Croat & R.N.Cirino","origin_type":"species","type_locality":"Colombia","citation_links":[{"url":"https://www.ipni.org/n/60439860-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:60439860-2","label":"POWO (Kew)"}],"known_habitats":"Colombia","collection_year":null,"publication_year":2005},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia","discovery_year":2005,"source_language":"en","first_description":"Croat & R.N.Cirino, Aroideana 28: 56 (-58; fig. 2) (2005)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Croat & R.N.Cirino"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 57;
