update public.cultivars set origins = $j$[{"body":"正式な学名記載はまだない（未記載種／暫定名）。東パナマ産の黒いベルベット葉群として園芸界に現れ、BVEP（Black Velvet Eastern Panama）として流通した個体群を基にしている。園芸・収集界の記録ではRory Antolak が現地材料を導入・維持し、antolakii の暫定名を用いるようになったとされる。Jay Vannini 等が ined.（未出版名）として扱っている旨の専門家記事がある一方、IPNI/POWO/Tropicos 等の正式登録には有効な記載が見つからない。近縁関係は A. dressleri 群や papillilaminum 系と比較されることが多く、分布情報の公開を避けるため出典間で差異がある。","trust":67,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-09-04","isAI":true,"name":"AI (gpt-5-mini + Web検索)"},"body_en":"Formal, published nomenclature for Anthurium antolakii is not available — the name is used provisionally in cultivation. The plant entered the hobby as “BVEP” (Black Velvet Eastern Panama), appearing in trade around 2020. Multiple dealer and expert accounts credit Rory Antolak with introducing and maintaining the wild material; Jay Vannini and others have referred to the taxon as A. \"antolakii\" (ined.) in specialist writing. No valid protologue or IPNI/POWO/Tropicos record has been found, so the name remains unpublished. Horticultural sources commonly compare this entity to velvet-leaf species (notably Anthurium dressleri and papillilaminum-like plants). Locality information is treated confidentially by collectors, and some secondary sources disagree about whether a formal publication exists or whether a Tropicos listing was temporary.","sources":[{"url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","label":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)"}],"verified":false,"parentage":null,"source_url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","structured":{"notes":"","collector":null,"author_name":null,"origin_type":"species","trade_names":["BVEP","Black Velvet Eastern Panama"],"introduced_by":"Rory Antolak が導入・維持（2020頃）","origin_region":"Panama（eastern; Guna Yala 高地が示唆される）","type_locality":null,"citation_links":[{"url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","label":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)"}],"known_habitats":"Panama（eastern; Guna Yala 高地が示唆される）","species_status":"undescribed","closest_species":"aff. Anthurium dressleri","collection_year":null,"first_seen_year":2020,"publication_year":null,"working_name_origin":"Rory Antolak に献名した暫定学名（antolakii）"},"trustClass":"trust--mid","source_name":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)","source_tier":"B","source_type":"ai_research","native_region":"Panama（eastern; Guna Yala 高地が示唆される）","discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Horticultural Books / Society Publications","source_tier_label_jp":"園芸書籍・学会資料","discoverer_or_breeder":null}]$j$::jsonb, name_status = $q$informal$q$, aliases = array[$q$BVEP$q$,$q$Black Velvet Eastern Panama$q$]::text[], formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 59;
update public.cultivars set origins = $j$[{"body":"ブラジルの造園家 Roberto Burle Marx に由来する栽培品種とされる（1981年頃に流通開始）。基となった種は未確定で、Monstera deliciosa との説がある。","trust":20,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"System"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"namer":"Roberto Burle Marx","notes":"ブラジルの造園家 Roberto Burle Marx に由来する栽培品種とされる（1981年頃に流通開始）。基となった種は未確定で、Monstera deliciosa との説がある。","origin_type":"clone","collector":null},"trustClass":"trust--low","source_name":"No source available","source_tier":"D","source_type":"none","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":null}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 74;
