update public.cultivars set origins = $j$[{"body":"Anthurium regale は 1866 年、Linden が Belgique Hort. xvi. 200 で記載した。タイプ産地は Peru。採集者は Gustav Wallis。分布は Peru（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-08-23","isAI":true,"name":"GBIF / Kew"},"body_en":"Anthurium regale was described by Linden in 1866 in Belgique Hort. xvi. 200. Type locality: Peru. Collected by Gustav Wallis. Distribution: Peru (POWO).","sources":[{"url":"https://www.gbif.org/species/2873074","label":"GBIF (Kew Backbone)"},{"url":"https://powo.science.kew.org/results?q=Anthurium%20regale","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://www.gbif.org/species/2873074","structured":{"notes":"","collector":"Gustav Wallis","author_name":"Linden","origin_type":"species","type_locality":"Peru","citation_links":[{"url":"https://www.ipni.org/n/85270-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85270-1","label":"POWO (Kew)"},{"url":"https://www.gbif.org/species/2873074","label":"GBIF (Kew Backbone)"}],"known_habitats":"Peru","collection_year":null,"publication_year":1866},"trustClass":"trust--high","source_name":"GBIF / Kew Backbone Taxonomy","source_tier":"S","source_type":"ipni_powo","native_region":"Peru","discovery_year":1866,"source_language":"en","first_description":"Linden, Belgique Hort. xvi. 200 (1866)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Linden"},{"body":"発表者: Linden (1866). 採取地: Peru.","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-04-09","isAI":false,"name":"User"},"body_en":"Published by Linden (1866). Locality: Peru.","sources":[{"url":"https://www.ipni.org/n/85270-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85270-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85270-1","structured":{"notes":"Anthurium regaleは、葉の形状が長楕円形で、表面は光沢があり、濃緑色を呈します。葉脈パターンは、平行脈で、葉の先端は尖ります。ペティオールは長く、太いです。植物の全体的な外見は、葉の美しい形状と色合いによって特徴づけられます。","collector":null,"author_name":"Linden","origin_type":"species","type_locality":"Peru","known_habitats":"Peru","species_subcategory":"species"},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"manual","native_region":"Peru","discovery_year":null,"source_language":"en","first_description":"Linden, Belgique Hort. 16: 200 (1866)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Linden"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 83;
