update public.cultivars set origins = $j$[{"body":"発表者: T.Moore (1875). 生息地: 不明. Platycerium willinckiiは、葉が長い楕円形で、表面は暗緑色、裏面は淡黄色をしている。葉の質感は硬い。葉脈のパターンは網状で、葉の先端は尖っている。葉柄は短く、太い。植物の全体的な外見は、他のPlatycerium属の種と似ているが、葉の形状や色が異なる。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/17177570-1"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177570-1"}],"structured":{"notes":"","collector":null,"author_name":"T.Moore","origin_type":"species","type_locality":"","citation_links":[{"url":"https://www.ipni.org/n/17177570-1"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177570-1"}],"known_habitats":"不明","publication_year":1875},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 90;
update public.cultivars set origins = $j$[{"body":"発表者: T.Moore (1878). 採取地: Queensland, Australia. 生息地: Queensland. Platycerium hilliiは、葉が広がった形状をしており、質感は硬い。葉の色は緑で、葉脈のパターンは網状である。ペティオールは短く、太い。葉の形状は楕円形で、先端は尖っている。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/17177500-1"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177500-1"}],"structured":{"notes":"","collector":null,"author_name":"T.Moore","origin_type":"species","type_locality":"Queensland, Australia","citation_links":[{"url":"https://www.ipni.org/n/17177500-1"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177500-1"}],"known_habitats":"Queensland","publication_year":1878},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 93;
update public.cultivars set origins = $j$[{"body":"発表者: Baker (1876). 採取地: Madagascar. 生息地: Madagascar. Platycerium ellisiiは、葉が長い楕円形で、濃い緑色をしています。葉の表面は滑らかで、葉脈は網状に広がっています。葉の付け根は太い毛で覆われています。植物全体に、独特の凹凸のある葉が特徴的です。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/17177480-1"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177480-1"}],"structured":{"notes":"","collector":null,"author_name":"Baker","origin_type":"species","type_locality":"Madagascar","citation_links":[{"url":"https://www.ipni.org/n/17177480-1"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177480-1"}],"known_habitats":"Madagascar","publication_year":1876},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 102;
update public.cultivars set origins = $j$[{"body":"発表者: Baker (1876). 採取地: Madagascar. 生息地: Madagascar. Platycerium madagascarienseはマダガスカル原産のシダ植物です。葉は長い葉柄に付いており、葉身は楕円形で濃緑色をしています。葉の表面は滑らかで、葉脈は網状に広がっています。葉の付け根には毛が生えていることがあります。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/17177510-1"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177510-1"}],"structured":{"notes":"","collector":null,"author_name":"Baker","origin_type":"species","type_locality":"Madagascar","citation_links":[{"url":"https://www.ipni.org/n/17177510-1"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17177510-1"}],"known_habitats":"Madagascar","publication_year":1876},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 104;
update public.cultivars set origins = $j$[{"body":"発表者: (Bonap.) Tardieu (1959). 採取地: Madagascar. 生息地: Madagascar. Platycerium quadridichotomumは、葉が二次的に分岐する特徴的な観葉植物です。葉の形状は楕円形で、表面は光沢があり、濃緑色をしています。葉脈のパターンは網状で、葉の先端は尖っています。葉の質感は厚く、革質です。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/17411090-1"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17411090-1"}],"structured":{"notes":"","collector":null,"author_name":"(Bonap.) Tardieu","origin_type":"species","type_locality":"Madagascar","citation_links":[{"url":"https://www.ipni.org/n/17411090-1"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:17411090-1"}],"known_habitats":"Madagascar","publication_year":1959},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 105;
update public.cultivars set origins = $j$[{"body":"発表者: Baker (1891). 採取地: Andes, Peru. 生息地: Peru, Bolivia. Platycerium andinumは、葉が長い披針形で、濃い緑色をしています。葉の表面は滑らかで、葉脈は網状に広がっています。葉の付け根には、毛が生えていることがあります。植物全体に、独特の凹凸が見られます。","trust":30,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-22","isAI":false,"name":"User"},"sources":[{"icon":"🌐","text":"https://www.ipni.org/n/201729-2"},{"icon":"🌐","text":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:201729-2"}],"structured":{"notes":"","collector":null,"author_name":"Baker","origin_type":"species","type_locality":"Andes, Peru","citation_links":[{"url":"https://www.ipni.org/n/201729-2"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:201729-2"}],"known_habitats":"Peru, Bolivia","publication_year":1891},"trustClass":"trust--low","source_type":"manual"}]$j$::jsonb, name_status = null, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 107;
update public.cultivars set origins = $j$[{"body":"Anthurium besseae（ボリビア産）とは別物として扱う。パナマ Darién 産として流通。","trust":30,"votes":{"agree":1,"disagree":0},"author":{"date":"2026-03-27","isAI":false,"name":"User"},"sources":[],"structured":{"notes":"Anthurium besseaeとは別物","collector":null,"author_name":null,"origin_type":"species","type_locality":null,"known_habitats":"Darién, Panama","species_subcategory":"aff"},"trustClass":"trust--low","source_type":"manual","body_en":"Treated as distinct from Anthurium besseae (Bolivia). Traded as material from Darién, Panama.","native_region":"Darién, Panama"}]$j$::jsonb, name_status = $q$informal$q$, aliases = null, formula_status = null, parent_b_id = null, parent_b_text = null, updated_at = now() where id = 108;
update public.cultivars set origins = $j$[{"body":"作出者: Chandra. 交配式: 'Dorayaki' original × 'Red Crystallinum' NSE. Anthurium 'Mystique A88' は Chandra によって作出された。Anthurium 'Dorayaki' original と Anthurium 'Red Crystallinum' NSE の交配式である\n\n'Mystique A88' にはoriginalがある。しかし生産ラインはoriginalのseedlingではなく、\n'Dorayaki' original×'Red Crystallinum' NSE\nのF1個体になる。","trust":30,"votes":{"agree":1,"disagree":0},"author":{"date":"2026-03-30","isAI":false,"name":"User"},"sources":[],"structured":{"notes":"Anthurium 'Mystique A88' は Mr Chandra によって作出された。Anthurium 'Dorayaki' original と Anthurium 'Red Crystallinum' NSE の交配式である\n\n'Mystique A88' にはoriginalがある。しかし生産ラインはoriginalのseedlingではなく、\n'Dorayaki' original×'Red Crystallinum' NSE\nのF1個体になる。 母株は 'Red Crystallinum' の NSE 系統。","breeder":"Chandra","formula":{"parentA":"Anthurium 'Dorayaki'","parentB":"Anthurium 'Red Crystallinum' (NSE)"},"origin_type":"hybrid","collector":null},"trustClass":"trust--low","source_type":"manual","discoverer_or_breeder":"Chandra"}]$j$::jsonb, name_status = null, aliases = array[$q$Mystique a88$q$]::text[], formula_status = $q$known$q$, parent_b_id = 52, parent_b_text = $q$Anthurium 'Red Crystallinum'$q$, updated_at = now() where id = 109;
